t.guides["forever/legacy/legacy-challenges"] = (function() return {
		["Adventure: explore the world map"] = "冒險：探索世界地圖",
		["Adventure: {npc:16042}"] = "冒險：{npc:16042}",
		["Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself."] = "職業可提供27點：每個職業達到25、45和60級。每個職業在整個帳號只計算一次，所以已經練過的職業再練第二個角色不會增加點數；新的職業才會。第一個達到25級的角色通常就會解鎖傳承系統本身。",
		["Classes: level 25"] = "職業：等級25",
		["Classes: level 45"] = "職業：等級45",
		["Classes: level 60"] = "職業：等級60",
		["Dire Maul East"] = "厄運之槌東區",
		["Dire Maul North"] = "厄運之槌北區",
		["Dire Maul West"] = "厄運之槌西區",
		["Dungeons: level 15-25"] = "地城：等級15-25",
		["Dungeons: level 26-45"] = "地城：等級26-45",
		["Dungeons: level 46-60"] = "地城：等級46-60",
		["Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Polestar guide \"{skill:171} 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System."] = "每個製造專業可提供3點，分別在150、225和300。每個專業的等級在整個帳號只計算一次。請參照Polestar指南「{skill:171} 1-300」（專業）。製造專業達到150也會解鎖傳承系統。",
		["Follow the Polestar guide \"{skill:164} 1-300\" (Professions)."] = "請參照Polestar指南「{skill:164} 1-300」（專業）。",
		["Follow the Polestar guide \"{skill:165} 1-300\" (Professions)."] = "請參照Polestar指南「{skill:165} 1-300」（專業）。",
